<script setup lang="ts">
import { computed, nextTick, onMounted, reactive, ref, watch } from 'vue';
import { request, session } from '../crm-api';
import ManualInvoiceForm from './ManualInvoiceForm.vue';

type Customer = { customer_id: number; company: string; customer_code?: string; primary_email?: string; email?: string };
type Invoice = { id: string; customer_id: number; kind: string; amount: string; gross?: string; currency: string; status: string; payment_status?: string; order_ids?: string[]; invoice_number?: string; created_at?: string; due_date?: string; received_at?: string; lines?: { description: string; amount: string }[]; rebate_allocations?: { rebate_id: string; month?: string; amount: string }[] };
type Credit = { id: string; customer_id: number; company?: string; month: string; amount: string; currency: string; used?: string; remaining?: string; claim_status?: string; claimable?: boolean; evidence?: string; allocations?: { invoice_id?: string; invoice_number?: string; amount?: string }[] };
type InvoiceDesignBlock = { id: string; label?: string; enabled: boolean; align: 'left'|'center'|'right'; width: number };
type InvoiceDesigns = Record<'deposit'|'balance'|'manual', { blocks: InvoiceDesignBlock[] }>;
type InvoiceTemplate = { company_name: string; gst_number: string; company_address: string; footer: string; deposit_note: string; balance_note: string; invoice_designs: InvoiceDesigns };
type PaymentDetails = { account_name: string; bank_name: string; account_number: string; reference_note: string; configured?: boolean };
type Settings = { payment_details: PaymentDetails; invoice_template: InvoiceTemplate };
const props = defineProps<{ admin: boolean; emailEnabled: boolean; emailMode: string }>();
const customers = ref<Customer[]>([]); const invoices = ref<Invoice[]>([]); const credits = ref<Credit[]>([]); const settings = ref<Settings | null>(null);
const pane = ref<'invoices'|'rebates'>('invoices'); const loading = ref(true); const busy = ref(false); const error = ref(''); const notice = ref('');
const query = ref(''); const customerFilter = ref(''); const statusFilter = ref(''); const kindFilter = ref(''); const createdFrom = ref(''); const createdTo = ref(''); const sortKey = ref<'created_at'|'due_date'|'amount'|'company'|'payment_status'>('created_at'); const sortDesc = ref(true);
const creditQuery = ref(''); const creditStatus = ref(''); const settingsOpen = ref(false); const newInvoiceOpen = ref(false); const previewInvoice = ref<Invoice|null>(null); const previewHtml = ref(''); const settingsBusy = ref(false);
const templateKind = ref<'deposit'|'balance'|'manual'>('deposit'); const templatePreview = ref(''); const templatePreviewBusy = ref(false); const selectedBlock = ref('logo');
const templatePreviewCanvas = ref<HTMLElement|null>(null); const templatePreviewScale = ref(0.5); let templatePreviewObserver:ResizeObserver|undefined;
const payment = reactive({ account_name:'', bank_name:'', account_number:'', reference_note:'' });
const blockIds = ['logo','company','heading','bill_to','order_lines','totals','payment','notes','footer'];
const blockLabels:Record<string,string> = {logo:'Logo',company:'Company details',heading:'Invoice title and dates',bill_to:'Customer details',order_lines:'Orders and items',totals:'GST and total',payment:'Payment details',notes:'Invoice note',footer:'Footer message'};
const initialDesign = ():InvoiceDesigns => Object.fromEntries((['deposit','balance','manual'] as const).map(kind=>[kind,{blocks:blockIds.map(id=>({id,label:blockLabels[id],enabled:true,align:'left' as const,width:220}))}])) as InvoiceDesigns;
const template = reactive<InvoiceTemplate>({ company_name:'VERA Shading Solutions', gst_number:'', company_address:'', footer:'', deposit_note:'Deposit of 60% of the order total. Amounts include GST.', balance_note:'Balance of each order after the deposit already paid. Amounts include GST.', invoice_designs:initialDesign() });
const activeBlocks = computed(()=>template.invoice_designs[templateKind.value]?.blocks||[]);
const editableBlocks = computed(()=>activeBlocks.value.map(block=>({...block,label:blockLabels[block.id]||block.id})));
const customerName = (id:number) => customers.value.find(c=>c.customer_id===id)?.company || 'Unknown customer';
const localDate = (value?:string) => value ? new Date(value.length===10 ? `${value}T00:00:00` : value).toLocaleDateString('en-NZ',{day:'numeric',month:'short',year:'numeric'}) : '—';
const money = (value?:string|number, currency='NZD') => `${currency} ${Number(value||0).toLocaleString('en-NZ',{minimumFractionDigits:2,maximumFractionDigits:2})}`;
const invoiceRows = computed(()=> invoices.value.filter(i=>{
  const customer=customerName(i.customer_id); const text=`${i.invoice_number||i.id} ${customer} ${i.order_ids?.join(' ')||''}`.toLowerCase();
  const created=String(i.created_at||'').slice(0,10);
  return (!query.value||text.includes(query.value.toLowerCase().trim())) && (!customerFilter.value||String(i.customer_id)===customerFilter.value) && (!statusFilter.value||paymentStatus(i)===statusFilter.value) && (!kindFilter.value||i.kind===kindFilter.value) && (!createdFrom.value||created>=createdFrom.value) && (!createdTo.value||created<=createdTo.value);
}).sort((a,b)=>{
  const av=sortKey.value==='company'?customerName(a.customer_id):sortKey.value==='payment_status'?paymentStatus(a):sortKey.value==='amount'?Number(a.amount||0):String(a[sortKey.value]||'');
  const bv=sortKey.value==='company'?customerName(b.customer_id):sortKey.value==='payment_status'?paymentStatus(b):sortKey.value==='amount'?Number(b.amount||0):String(b[sortKey.value]||'');
  const cmp=typeof av==='number'&&typeof bv==='number'?av-bv:String(av).localeCompare(String(bv)); return sortDesc.value?-cmp:cmp;
}));
const creditRows = computed(()=>credits.value.filter(c=>`${c.company||customerName(c.customer_id)} ${c.month} ${c.id}`.toLowerCase().includes(creditQuery.value.toLowerCase().trim()) && (!creditStatus.value||c.claim_status===creditStatus.value))
  .sort((a,b)=>(a.company||customerName(a.customer_id)).localeCompare(b.company||customerName(b.customer_id)) || b.month.localeCompare(a.month)));
const creditGroups = computed(()=>{ const groups=new Map<number,{customer_id:number;company:string;credits:Credit[]}>(); for(const credit of creditRows.value){const group=groups.get(credit.customer_id)||{customer_id:credit.customer_id,company:credit.company||customerName(credit.customer_id),credits:[]};group.credits.push(credit);groups.set(credit.customer_id,group)} return [...groups.values()] });
const paymentStatus=(invoice:Invoice)=>invoice.payment_status==='received'||invoice.payment_status==='paid'?'paid':invoice.status==='draft'?'draft':'unpaid';
const invoiceKind=(kind:string)=>kind==='deposit'?'Deposit':kind==='balance'?'Balance':'Manual';
async function load(){ loading.value=true; error.value=''; try { const [c,i,r]=await Promise.all([request<Customer[]>('operations/customers'),request<Invoice[]>('operations/invoices'),request<{credits:Credit[]}>('operations/rebates')]); customers.value=c; invoices.value=i; credits.value=r.credits; if(props.admin) settings.value=await request<Settings>('operations/settings'); fillSettings(); } catch(e){error.value=e instanceof Error?e.message:String(e)} finally{loading.value=false} }
function fillSettings(){ if(!settings.value)return; Object.assign(payment,settings.value.payment_details); Object.assign(template,settings.value.invoice_template); const saved=template.invoice_designs||{} as InvoiceDesigns; for(const kind of ['deposit','balance','manual'] as const){ const current=saved[kind]?.blocks||[]; const byId=new Map(current.map(block=>[block.id,block])); const ordered=current.map(block=>({...block,label:blockLabels[block.id]||block.id})); for(const id of blockIds)if(!byId.has(id))ordered.push({id,label:blockLabels[id],enabled:true,align:'left',width:220}); saved[kind]={blocks:ordered}; } template.invoice_designs=saved; }
function sortBy(key:typeof sortKey.value){ if(sortKey.value===key)sortDesc.value=!sortDesc.value; else {sortKey.value=key;sortDesc.value=key!=='company'} }
async function created(invoice:Invoice){ newInvoiceOpen.value=false; await load(); void openPreview(invoice); }
async function openPreview(invoice:Invoice){ error.value=''; previewInvoice.value=invoice; try { const response=await request<{html:string}>(`operations/invoices/${encodeURIComponent(invoice.id)}/mail-preview`); previewHtml.value=response.html; } catch(e){previewHtml.value=''; error.value=e instanceof Error?e.message:String(e)} }
async function send(invoice:Invoice){ busy.value=true; error.value=''; notice.value=''; try{ const sent=await request<Invoice>(`operations/invoices/${encodeURIComponent(invoice.id)}/send`,{}); notice.value=`${sent.invoice_number||sent.id}: ${sent.status}`; await load(); previewInvoice.value=null; }catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false} }
async function markReceived(invoice:Invoice){ const note=window.prompt('Confirm the payment has arrived. Add a note (optional):','Payment received'); if(note===null)return; busy.value=true; error.value=''; try{await request(`operations/invoices/${encodeURIComponent(invoice.id)}/received`,{note:note.trim()||'Payment received'}); await load();}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false} }
async function setClaim(credit:Credit,event:Event){ const value=(event.target as HTMLSelectElement).value; busy.value=true; error.value=''; try{await request(`operations/rebates/${encodeURIComponent(credit.id)}/claim-status`,{claim_status:value}); const result=await request<{credits:Credit[]}>('operations/rebates'); credits.value=result.credits;}catch(e){error.value=e instanceof Error?e.message:String(e); await load()}finally{busy.value=false} }
function paymentPayload(){ return { account_name:payment.account_name, bank_name:payment.bank_name, account_number:payment.account_number, reference_note:payment.reference_note }; }
async function saveSettings(){ if(!props.admin)return; settingsBusy.value=true; error.value=''; notice.value=''; try{settings.value=await request<Settings>('operations/settings',{payment_details:paymentPayload(),invoice_template:templatePayload()}); fillSettings(); notice.value='Invoice templates and payment details saved.'; settingsOpen.value=false;}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{settingsBusy.value=false} }
function moveBlock(index:number,delta:number){ const blocks=activeBlocks.value; const target=index+delta; if(target<0||target>=blocks.length)return; const next=[...blocks]; [next[index],next[target]]=[next[target],next[index]]; template.invoice_designs[templateKind.value].blocks=next; }
function changeBlock(block:InvoiceDesignBlock,key:'align'|'width'|'enabled',value:string|number|boolean){ const current=activeBlocks.value.find(item=>item.id===block.id); if(!current)return; if(key==='enabled'&&(block.id==='order_lines'||block.id==='totals'))return; Object.assign(current,{[key]:value}); }
function templatePayload(){ return { company_name:template.company_name, gst_number:template.gst_number, company_address:template.company_address, footer:template.footer, deposit_note:template.deposit_note, balance_note:template.balance_note, invoice_designs:Object.fromEntries((['deposit','balance','manual'] as const).map(kind=>[kind,{blocks:template.invoice_designs[kind].blocks.map(({id,enabled,align,width})=>({id,enabled,align,width}))}])) }; }
let previewTimer:number|undefined;
async function loadTemplatePreview(){ if(!settingsOpen.value)return; templatePreviewBusy.value=true; try{const result=await request<{html:string}>('operations/invoice-template-preview',{kind:templateKind.value,payment_details:paymentPayload(),invoice_template:templatePayload()});templatePreview.value=result.html;}catch(e){templatePreview.value='';error.value=e instanceof Error?e.message:String(e)}finally{templatePreviewBusy.value=false} }
function fitInvoicePage(){ const canvas=templatePreviewCanvas.value; if(!canvas)return; templatePreviewScale.value=Math.max(0.1,Math.min((canvas.clientWidth-24)/794,(canvas.clientHeight-24)/1123)); }
watch(settingsOpen,async open=>{await nextTick();templatePreviewObserver?.disconnect();if(!open)return;fitInvoicePage();if(templatePreviewCanvas.value){templatePreviewObserver=new ResizeObserver(fitInvoicePage);templatePreviewObserver.observe(templatePreviewCanvas.value)}});
watch([settingsOpen,templateKind,template,payment],()=>{if(!settingsOpen.value)return;window.clearTimeout(previewTimer);previewTimer=window.setTimeout(()=>void loadTemplatePreview(),250)},{deep:true});
async function openPdf(invoice:Invoice){ try{ const response=await fetch(`/api/operations/invoices/${encodeURIComponent(invoice.id)}/pdf`,{headers:session.token?{Authorization:`Bearer ${session.token}`}:{}}); if(!response.ok)throw new Error('Could not open invoice PDF'); const url=URL.createObjectURL(await response.blob()); window.open(url,'_blank','noopener'); setTimeout(()=>URL.revokeObjectURL(url),60000);}catch(e){error.value=e instanceof Error?e.message:String(e)} }
onMounted(load);
</script>

<template>
  <main class="accounting">
    <header class="page-head"><div><p class="eyebrow">VERA · FINANCE</p><h1>Accounting</h1><p>Manage customer invoices and monthly rebates from the same records used in the customer portal.</p></div><div class="head-actions"><button v-if="pane==='invoices' && admin" class="primary" @click="newInvoiceOpen=true">＋ New invoice</button><button v-if="pane==='invoices' && admin" class="secondary" @click="settingsOpen=true">Invoice settings</button><button class="secondary" @click="load" :disabled="loading">Refresh</button></div></header>
    <p v-if="error" class="notice error" role="alert">{{ error }}</p><p v-if="notice" class="notice success" role="status">{{ notice }}</p>
    <nav class="tabs" role="tablist"><button role="tab" :aria-selected="pane==='invoices'" :class="{active:pane==='invoices'}" @click="pane='invoices'">Invoice <span>{{ invoices.length }}</span></button><button role="tab" :aria-selected="pane==='rebates'" :class="{active:pane==='rebates'}" @click="pane='rebates'">Rebate <span>{{ credits.length }}</span></button></nav>
    <section v-if="pane==='invoices'" class="panel">
      <header class="panel-head"><div><h2>Invoices</h2><p>Invoice history, due dates and payment status.</p></div><strong>{{ invoiceRows.length }} / {{ invoices.length }}</strong></header>
      <div class="filters"><label>Search<input v-model="query" type="search" placeholder="Invoice, customer or order" /></label><label>Type<select v-model="kindFilter"><option value="">All types</option><option value="deposit">Deposit</option><option value="balance">Balance</option><option value="manual">Manual</option></select></label><label>Created from<input v-model="createdFrom" type="date" /></label><label>Created to<input v-model="createdTo" type="date" /></label></div>
      <div v-if="loading" class="empty">Loading invoices…</div><div v-else class="table-scroll"><table><thead><tr><th><button type="button" @click="sortBy('created_at')">Invoice / Created ↕</button></th><th><div class="invoice-header-filter"><button type="button" @click="sortBy('company')">Customer ↕</button><select v-model="customerFilter" aria-label="Filter invoices by customer"><option value="">All customers</option><option v-for="c in customers" :key="c.customer_id" :value="String(c.customer_id)">{{ c.company }}</option></select></div></th><th>Type</th><th><button type="button" @click="sortBy('due_date')">Due date ↕</button></th><th><button type="button" @click="sortBy('amount')">Amount</button></th><th>Paid date</th><th><div class="invoice-header-filter"><button type="button" @click="sortBy('payment_status')">Payment status ↕</button><select v-model="statusFilter" aria-label="Filter invoices by payment status"><option value="">All statuses</option><option value="draft">Draft</option><option value="unpaid">Unpaid</option><option value="paid">Paid</option></select></div></th><th>Actions</th></tr></thead><tbody><tr v-for="invoice in invoiceRows" :key="invoice.id"><td><strong>{{ invoice.invoice_number||invoice.id }}</strong><small>{{ localDate(invoice.created_at) }}</small></td><td>{{ customerName(invoice.customer_id) }}</td><td>{{ invoiceKind(invoice.kind) }}</td><td>{{ localDate(invoice.due_date) }}</td><td>{{ money(invoice.amount,invoice.currency) }}</td><td>{{ localDate(invoice.received_at) }}</td><td><span class="status" :class="paymentStatus(invoice)">{{ paymentStatus(invoice) }}</span><small v-if="invoice.status && invoice.status!=='sent'">{{ invoice.status }}</small></td><td class="actions"><button class="text" @click="openPreview(invoice)">Preview</button><button class="text" @click="openPdf(invoice)">PDF</button><button v-if="invoice.status==='draft' || invoice.status==='not_configured' || invoice.status==='demo_suppressed'" class="text" :disabled="busy" @click="send(invoice)">Send</button><button v-if="invoice.kind!=='deposit' && paymentStatus(invoice)!=='paid' && invoice.status!=='draft'" class="text" :disabled="busy" @click="markReceived(invoice)">Mark paid</button><small v-if="invoice.kind==='deposit' && paymentStatus(invoice)!=='paid'">Confirm deposit in Orders</small></td></tr><tr v-if="!loading&&!invoiceRows.length"><td colspan="8" class="empty">No invoices match these filters.</td></tr></tbody></table></div>
    </section>
    <section v-else class="panel">
      <header class="panel-head"><div><h2>Monthly rebates</h2><p>Automatically calculated from deposit paid dates. Claim status is shared with each customer’s My Rebate page.</p></div><strong>{{ creditRows.length }} credits</strong></header>
      <div class="filters"><label>Search<input v-model="creditQuery" type="search" placeholder="Customer or month" /></label><label>Claim status<select v-model="creditStatus"><option value="">All statuses</option><option value="unclaimed">Unclaimed</option><option value="partially_claimed">Partially claimed</option><option value="claimed">Claimed</option></select></label></div>
      <div v-if="loading" class="empty">Loading rebates…</div><div v-else class="rebate-groups"><details v-for="group in creditGroups" :key="group.customer_id" class="rebate-group" open><summary><strong>{{ group.company }}</strong><span>{{ group.credits.length }} months</span><b>{{ money(group.credits.reduce((sum,c)=>sum+Number(c.amount||0),0)) }} earned</b></summary><div class="table-scroll"><table><thead><tr><th>Month</th><th>Rebate earned</th><th>Claimed</th><th>Available</th><th>Claimed on invoice</th><th>Status</th></tr></thead><tbody><tr v-for="credit in group.credits" :key="credit.id"><td>{{ credit.month }}</td><td>{{ money(credit.amount,credit.currency) }}</td><td>{{ money(credit.used,credit.currency) }}</td><td>{{ money(credit.remaining,credit.currency) }}</td><td><span v-if="credit.allocations?.length">{{ credit.allocations.map(a=>a.invoice_number||a.invoice_id).filter(Boolean).join(', ') }}</span><span v-else>—</span></td><td><select :value="credit.claim_status||'unclaimed'" :disabled="!admin || busy || !!credit.allocations?.some(a=>a.invoice_id)" @change="setClaim(credit,$event)"><option value="unclaimed">Unclaimed</option><option value="claimed">Claimed</option><option v-if="credit.claim_status==='partially_claimed'" value="partially_claimed">Partially claimed</option></select></td></tr></tbody></table></div></details><p v-if="!creditGroups.length" class="empty">No rebates match these filters.</p></div>
    </section>
    <div v-if="newInvoiceOpen" class="overlay" @click.self="newInvoiceOpen=false"><section class="dialog"><header><h2>New invoice</h2><button class="close" @click="newInvoiceOpen=false">×</button></header><ManualInvoiceForm :customers="customers" locale="en" @created="created" /></section></div>
    <div v-if="settingsOpen" class="overlay" @click.self="settingsOpen=false"><section class="dialog settings-dialog designer-dialog"><header><div><p class="eyebrow">ACCOUNTING · INVOICE</p><h2>Invoice templates</h2><p class="dialog-subtitle">Arrange the invoice blocks and see the result before saving.</p></div><button class="close" @click="settingsOpen=false">×</button></header><form @submit.prevent="saveSettings"><nav class="template-tabs" aria-label="Invoice template type"><button v-for="kind in (['deposit','balance','manual'] as const)" :key="kind" type="button" :class="{active:templateKind===kind}" @click="templateKind=kind">{{ kind==='deposit'?'Deposit invoice':kind==='balance'?'Balance invoice':'Manual invoice' }}</button></nav><div class="designer-layout"><div class="designer-controls"><section class="editor-card"><h3>Page layout</h3><p>Move sections up or down. Choose alignment and logo width.</p><ol class="layout-blocks"><li v-for="(block,index) in editableBlocks" :key="block.id" :class="{selected:selectedBlock===block.id}" @click="selectedBlock=block.id"><div class="block-top"><label><input type="checkbox" :checked="block.enabled" :disabled="block.id==='order_lines'||block.id==='totals'" @click.stop @change="changeBlock(block,'enabled',($event.target as HTMLInputElement).checked)" /><strong>{{ block.label }}</strong></label><span class="move-actions"><button type="button" :disabled="index===0" aria-label="Move up" @click.stop="moveBlock(index,-1)">↑</button><button type="button" :disabled="index===editableBlocks.length-1" aria-label="Move down" @click.stop="moveBlock(index,1)">↓</button></span></div><div v-if="selectedBlock===block.id" class="block-options"><label>Alignment<select :value="block.align" @change="changeBlock(block,'align',($event.target as HTMLSelectElement).value)"><option value="left">Left</option><option value="center">Center</option><option value="right">Right</option></select></label><label v-if="block.id==='logo'">Logo width (px)<input type="number" min="80" max="560" :value="block.width" @input="changeBlock(block,'width',Number(($event.target as HTMLInputElement).value))" /></label></div></li></ol></section><section class="editor-card"><h3>Invoice content</h3><div class="settings-grid"><label>Company name<input v-model="template.company_name" maxlength="200" required /></label><label>GST number<input v-model="template.gst_number" maxlength="80" /></label><label class="wide">Company address<textarea v-model="template.company_address" rows="2" maxlength="500" /></label><label v-if="templateKind==='deposit'" class="wide">Deposit note<textarea v-model="template.deposit_note" rows="2" maxlength="500" /></label><label v-if="templateKind==='balance'" class="wide">Balance note<textarea v-model="template.balance_note" rows="2" maxlength="500" /></label><label class="wide">Footer message<textarea v-model="template.footer" rows="2" maxlength="1000" /></label></div><details class="payment-editor"><summary>Payment details</summary><div class="settings-grid"><label>Account name<input v-model="payment.account_name" maxlength="200" /></label><label>Bank<input v-model="payment.bank_name" maxlength="200" /></label><label>Account number<input v-model="payment.account_number" maxlength="100" /></label><label>Payment note<input v-model="payment.reference_note" maxlength="500" /></label></div></details></section></div><section class="template-preview"><div class="preview-heading"><strong>Live invoice preview · A4</strong><span>{{ templatePreviewBusy?'Updating…':'Print view' }}</span></div><div ref="templatePreviewCanvas" class="template-preview-canvas"><iframe v-if="templatePreview" :srcdoc="templatePreview" :style="{'--a4-scale':templatePreviewScale}" title="A4 invoice print preview" sandbox="allow-same-origin" scrolling="no" /><div v-else class="preview-loading">Preparing A4 preview…</div></div></section></div><footer><button class="primary" :disabled="settingsBusy">{{ settingsBusy?'Saving…':'Save templates and payment details' }}</button><button type="button" class="secondary" @click="settingsOpen=false">Cancel</button></footer></form></section></div>
    <div v-if="previewInvoice" class="overlay" @click.self="previewInvoice=null"><section class="dialog preview-dialog"><header><div><p class="eyebrow">{{ invoiceKind(previewInvoice.kind) }} INVOICE</p><h2>{{ previewInvoice.invoice_number||previewInvoice.id }}</h2></div><button class="close" @click="previewInvoice=null">×</button></header><div class="preview-meta"><span>Customer: <strong>{{ customerName(previewInvoice.customer_id) }}</strong></span><span>Amount incl. GST: <strong>{{ money(previewInvoice.amount,previewInvoice.currency) }}</strong></span><span>Due: <strong>{{ localDate(previewInvoice.due_date) }}</strong></span><button class="secondary" @click="openPdf(previewInvoice)">Open PDF</button></div><iframe v-if="previewHtml" :srcdoc="previewHtml" title="Invoice preview" sandbox="allow-same-origin" /><p v-else class="empty">Loading preview…</p><footer><button v-if="previewInvoice.status==='draft'||previewInvoice.status==='not_configured'||previewInvoice.status==='demo_suppressed'" class="primary" :disabled="busy" @click="send(previewInvoice)">{{ busy?'Sending…':'Send invoice' }}</button><button class="secondary" @click="previewInvoice=null">Close</button></footer></section></div>
  </main>
